module.exports = "<div [ngClass]=\"getTableClasses()\" [ngStyle]=\"cssVars\">\n  @if (showSearch() || filtersVisible()) {\n    <header class=\"bmb_table_lite-header\">\n      @if (showSearch()) {\n        <section class=\"bmb_table_lite-search\">\n          <bmb-input\n            class=\"bmb_table_lite-input\"\n            [type]=\"'text'\"\n            [placeholder]=\"'Buscar'\"\n            [disabled]=\"false\"\n            [icon]=\"'search'\"\n            [appearance]=\"'normal'\"\n            [control]=\"searchControl\"\n          ></bmb-input>\n          <bmb-action-icon\n            [idElement]=\"''\"\n            [icon]=\"'filter_list'\"\n            [iconSize]=\"24\"\n            (buttonClick)=\"toggleFilters()\"\n          ></bmb-action-icon>\n        </section>\n      }\n      <div class=\"bmb_table_lite-filter\">\n        @if (filtersVisible()) {\n          @for (column of parsedFiltersColumns(); track $index) {\n            <section class=\"bmb_table_lite-filter-item\">\n              @switch (column.type) {\n                @case ('number') {\n                  <div class=\"bmb_table_lite-filter-item-number\">\n                    <bmb-input\n                      [label]=\"column.label + ' mínimo'\"\n                      [type]=\"'number'\"\n                      [placeholder]=\"'Mín'\"\n                      [appearance]=\"'normal'\"\n                      [control]=\"getFormControl(column.dataKey + '_min')\"\n                    />\n                    <bmb-input\n                      [label]=\"column.label + ' máximo'\"\n                      [type]=\"'number'\"\n                      [placeholder]=\"'Máx'\"\n                      [appearance]=\"'normal'\"\n                      [control]=\"getFormControl(column.dataKey + '_max')\"\n                    />\n                  </div>\n                }\n                @case ('date') {\n                  <bmb-date-range\n                    [placeholderStartDate]=\"'Desde'\"\n                    [placeholderEndDate]=\"'Hasta'\"\n                    [icon]=\"'calendar_month'\"\n                    [dateFormat]=\"'dd/MM/yyyy'\"\n                    [controlStart]=\"getFormControl(column.dataKey + '_from')\"\n                    [controlEnd]=\"getFormControl(column.dataKey + '_to')\"\n                    (startDateChange)=\"\n                      getFormControl(column.dataKey + '_from').setValue($event)\n                    \"\n                    (endDateChange)=\"\n                      getFormControl(column.dataKey + '_to').setValue($event)\n                    \"\n                  />\n                }\n                @default {\n                  <bmb-input\n                    [label]=\"column.label\"\n                    [placeholder]=\"'Filtrar'\"\n                    [control]=\"getFormControl(column.dataKey + '_contains')\"\n                  />\n                }\n              }\n            </section>\n          }\n        }\n      </div>\n    </header>\n  }\n\n  <div class=\"bmb_table_lite-container\">\n    <section class=\"bmb_table_lite-container-table\">\n      <div class=\"bmb_table_lite-row bmb_table_lite-row--header\">\n        @if (tableConfig?.isSelectable) {\n          <div class=\"bmb_table_lite-th bmb_table_lite-checkbox\">\n            <bmb-checkbox\n              (change)=\"$event ? toggleAllRows() : null\"\n              [checked]=\"isAllSelected()\"\n              [indeterminate]=\"selection.hasValue() && !isAllSelected()\"\n              [ariaLabel]=\"checkboxLabel()\"\n              [disabled]=\"false\"\n            />\n          </div>\n        }\n\n        @if (tableConfig?.isExpandible) {\n          <div class=\"bmb_table_lite-th bmb_table_lite-expand\">&nbsp;</div>\n        }\n\n        @for (\n          column of tableColumns;\n          track trackByColumn(column);\n          let i = $index\n        ) {\n          <div\n            class=\"bmb_table_lite-th\"\n            [ngClass]=\"getHeaderCellClasses(i)\"\n            [title]=\"\n              lang() === 'es' ? column.label : column.labelEn || column.label\n            \"\n          >\n            <ng-container *ngIf=\"column.icon\">\n              <bmb-icon [icon]=\"column.icon\"></bmb-icon>\n            </ng-container>\n\n            @if (column.htmlLabel) {\n              <ng-template\n                [ngTemplateOutlet]=\"column.htmlLabel\"\n                [ngTemplateOutletContext]=\"{ column: column, index: i }\"\n              ></ng-template>\n            } @else {\n              <span class=\"bmb_table_lite-th-text\">\n                {{\n                  lang() === 'es'\n                    ? column.label\n                    : column.labelEn || column.label\n                }}\n              </span>\n            }\n          </div>\n        }\n\n        @if (tableConfig?.showActions) {\n          <div class=\"bmb_table_lite-th bmb_table_lite-actions\"></div>\n        }\n      </div>\n\n      @for (row of pageSlice; track trackByRow(row); let rIndex = $index) {\n        <div\n          class=\"bmb_table_lite-row\"\n          role=\"button\"\n          tabindex=\"0\"\n          (click)=\"onSelectRow(row)\"\n          (keydown.enter)=\"onSelectRow(row)\"\n          (keydown.space)=\"onSelectRow(row)\"\n          [ngClass]=\"{\n            'bmb_table_lite-even': isEven(rIndex),\n            'bmb_table_lite-odd': isOdd(rIndex),\n            'bmb_table_lite-expandible': expandedElement === row\n          }\"\n        >\n          @if (tableConfig?.isSelectable) {\n            <div class=\"bmb_table_lite-td bmb_table_lite-checkbox\">\n              <bmb-checkbox\n                (change)=\"$event ? selection.toggle(row) : null; onSelect()\"\n                [checked]=\"selection.isSelected(row)\"\n                [ariaLabel]=\"checkboxLabel(row)\"\n                [disabled]=\"false\"\n                onkeypress=\"$event.stopPropagation()\"\n              />\n            </div>\n          }\n\n          @if (tableConfig?.isExpandible) {\n            <div class=\"bmb_table_lite-td bmb_table_lite-expand\">\n              <button\n                type=\"button\"\n                class=\"bmb_btn-icon\"\n                aria-label=\"expand row\"\n                (click)=\"\n                  expandedElement = expandedElement === row ? null : row;\n                  $event.stopPropagation()\n                \"\n              >\n                <bmb-icon\n                  [icon]=\"\n                    expandedElement === row ? 'zoom_in_map' : 'zoom_out_map'\n                  \"\n                ></bmb-icon>\n              </button>\n            </div>\n          }\n\n          @for (\n            column of tableColumns;\n            track trackByColumn(column);\n            let i = $index\n          ) {\n            <div\n              class=\"bmb_table_lite-td\"\n              [ngClass]=\"getCellClasses(row, column.dataKey, i)\"\n              [title]=\"row[column.dataKey]?.propertyName || row[column.dataKey]\"\n            >\n              @if (isTemplateRef(row[column.dataKey + 'Template'])) {\n                <ng-template\n                  [ngTemplateOutlet]=\"row[column.dataKey + 'Template']\"\n                  [ngTemplateOutletContext]=\"{ row: row }\"\n                ></ng-template>\n              } @else {\n                <span>\n                  {{ row[column.dataKey]?.propertyName || row[column.dataKey] }}\n                </span>\n              }\n            </div>\n          }\n\n          @if (tableConfig?.showActions) {\n            <div class=\"bmb_table_lite-td bmb_table_lite-actions\">\n              @if (\n                tableColumns.length &&\n                tableColumns[tableColumns.length - 1].templateActions\n              ) {\n                <ng-template\n                  [ngTemplateOutlet]=\"\n                    tableColumns[tableColumns.length - 1].templateActions!\n                  \"\n                  [ngTemplateOutletContext]=\"{ row: row }\"\n                ></ng-template>\n              } @else {\n                <ng-template\n                  [ngTemplateOutlet]=\"actionTemplate()!\"\n                  [ngTemplateOutletContext]=\"{ row: row }\"\n                ></ng-template>\n              }\n            </div>\n          }\n        </div>\n\n        @if (tableConfig?.isExpandible) {\n          <div\n            class=\"bmb_table_lite-row bmb_table_lite-details\"\n            [class.bmb_table_lite-expanded]=\"expandedElement === row\"\n          >\n            <div class=\"bmb_table_lite-detail\" *ngIf=\"expandedElement === row\">\n              <ng-container\n                *ngTemplateOutlet=\"detailTemplate(); context: { row: row }\"\n              ></ng-container>\n            </div>\n          </div>\n        }\n      }\n    </section>\n\n    @if (tableConfig?.isPaginable) {\n      <div class=\"bmb_table_lite-paginator\">\n        <span class=\"bmb_table_lite-paginator-text\">\n          {{ getPaginationText() }}\n        </span>\n\n        <button\n          class=\"bmb_table_lite-paginator-btn\"\n          [disabled]=\"isFirstPage() || isSinglePage()\"\n          (click)=\"goToFirstPage()\"\n        >\n          <bmb-icon\n            icon=\"keyboard_double_arrow_left\"\n            class=\"bmb_table_lite-paginator-icon\"\n          />\n        </button>\n\n        <button\n          class=\"bmb_table_lite-paginator-btn\"\n          [disabled]=\"isFirstPage() || isSinglePage()\"\n          (click)=\"goToPreviousPage()\"\n        >\n          <bmb-icon\n            icon=\"keyboard_arrow_left\"\n            class=\"bmb_table_lite-paginator-icon\"\n          />\n        </button>\n\n        <button\n          class=\"bmb_table_lite-paginator-btn\"\n          [disabled]=\"isLastPage() || isSinglePage()\"\n          (click)=\"goToNextPage()\"\n        >\n          <bmb-icon\n            icon=\"keyboard_arrow_right\"\n            class=\"bmb_table_lite-paginator-icon\"\n          />\n        </button>\n\n        <button\n          class=\"bmb_table_lite-paginator-btn\"\n          [disabled]=\"isLastPage() || isSinglePage()\"\n          (click)=\"goToLastPage()\"\n        >\n          <bmb-icon\n            icon=\"keyboard_double_arrow_right\"\n            class=\"bmb_table_lite-paginator-icon\"\n          />\n        </button>\n      </div>\n    }\n  </div>\n</div>\n";

